import numpy as np

from xarray.core.datatree import Variable

def align_nd_chunks(
    nd_v_chunks: tuple[tuple[int, ...], ...],
    nd_backend_chunks: tuple[tuple[int, ...], ...],
) -> tuple[tuple[int, ...], ...]:
    if len(nd_v_chunks) != len(nd_backend_chunks):
        raise ValueError("The number of dimensions between backend and variable chunks don't match.")

    aligned_nd_chunks = []
    for v_chunks, backend_chunks in zip(nd_v_chunks, nd_backend_chunks):
        if sum(v_chunks) != sum(backend_chunks):
            raise ValueError("The total number of elements in backend chunks doesn't match the variable chunks.")

        if len(v_chunks) == 1 and len(backend_chunks) == 1:
            aligned_nd_chunks.append(v_chunks)
            continue

        fixed_chunk = max(backend_chunks)

        if len(backend_chunks) > 2:
            for c in backend_chunks[1:-1]:
                if c != fixed_chunk:
                    raise ValueError("Backend chunks are not uniformly sized (excluding border chunks).")

        max_chunk = max(fixed_chunk, *v_chunks)

        padded_v_chunks = list(v_chunks)
        padded_v_chunks[0] += (fixed_chunk - backend_chunks[0])
        if len(v_chunks) > 1:
            padded_v_chunks[-1] += (fixed_chunk - backend_chunks[-1])
        else:
            padded_v_chunks[0] += (fixed_chunk - backend_chunks[-1])

        aligned = []
        unfilled_size = 0

        for v_chunk in padded_v_chunks:
            last_aligned_chunk = aligned[-1] if unfilled_size > 0 else 0
            current_chunk_size = last_aligned_chunk + v_chunk

            if unfilled_size > 0:
                aligned.pop()

            while current_chunk_size > max_chunk:
                max_increase = (max_chunk - last_aligned_chunk) - ((max_chunk - last_aligned_chunk - unfilled_size) % fixed_chunk)
                split_size = last_aligned_chunk + max_increase
                aligned.append(split_size)

                current_chunk_size -= split_size
                last_aligned_chunk = 0
                unfilled_size = (fixed_chunk - split_size % fixed_chunk) % fixed_chunk

            aligned.append(current_chunk_size)
            unfilled_size = (fixed_chunk - current_chunk_size % fixed_chunk) % fixed_chunk

        aligned[0] -= (fixed_chunk - backend_chunks[0])
        if len(aligned) > 1:
            aligned[-1] -= (fixed_chunk - backend_chunks[-1])
        else:
            aligned[0] -= (fixed_chunk - backend_chunks[-1])

        if len(aligned) > 1:
            if aligned[-1] + aligned[-2] <= max_chunk and aligned[-1] != v_chunks[-1]:
                aligned = aligned[:-2] + [aligned[-2] + aligned[-1]]

        if len(aligned) > 1:
            if aligned[0] + aligned[1] <= max_chunk and aligned[0] != v_chunks[0]:
                aligned = [aligned[0] + aligned[1]] + aligned[2:]

        aligned_nd_chunks.append(tuple(aligned))

    return tuple(aligned_nd_chunks)


def build_grid_chunks(size: int, chunk_size: int, region: slice | None = None) -> tuple[int, ...]:
    if region is None:
        region = slice(0, size)

    start = region.start or 0
    stop = region.stop if region.stop is not None else size

    first_chunk_size = chunk_size - (start % chunk_size)
    if first_chunk_size >= (stop - start):
        return (stop - start,)

    chunks = [first_chunk_size]
    remaining = (stop - start) - first_chunk_size
    while remaining > 0:
        if remaining >= chunk_size:
            chunks.append(chunk_size)
            remaining -= chunk_size
        else:
            chunks.append(remaining)
            remaining = 0

    return tuple(chunks)


def grid_rechunk(v: Variable, enc_chunks: tuple[int, ...], region: tuple[slice, ...]) -> Variable:
    if v.chunks is None:
        return v

    nd_backend_chunks = []
    for dim_size, chunk_size, r in zip(v.shape, enc_chunks, region):
        start = r.start or 0
        stop = r.stop if r.stop is not None else start + dim_size
        backend_chunks = build_grid_chunks(size=stop, chunk_size=chunk_size, region=r)
        nd_backend_chunks.append(backend_chunks)

    nd_backend_chunks = tuple(nd_backend_chunks)
    aligned_chunks = align_nd_chunks(v.chunks, nd_backend_chunks)
    return v.chunk(aligned_chunks)


def validate_grid_chunks_alignment(
    nd_v_chunks: tuple[tuple[int, ...], ...] | None,
    enc_chunks: tuple[int, ...],
    backend_shape: tuple[int, ...],
    region: tuple[slice, ...],
    allow_partial_chunks: bool,
    name: str,
):
    if nd_v_chunks is None:
        return
    base_error = (
        "Specified Zarr chunks encoding['chunks']={enc_chunks!r} for "
        "variable named {name!r} would overlap multiple Dask chunks. "
        "Please check the Dask chunks at position {v_chunk_pos} and "
        "{v_chunk_pos_next}, on axis {axis}, they are overlapped "
        "on the same Zarr chunk in the region {region}. "
        "Writing this array in parallel with Dask could lead to corrupted data. "
        "To resolve this issue, consider one of the following options: "
        "- Rechunk the array using `chunk()`. "
        "- Modify or delete `encoding['chunks']`. "
        "- Set `safe_chunks=False`. "
        "- Enable automatic chunks alignment with `align_chunks=True`."
    )

    for axis, chunk_size, v_chunks, interval, size in zip(
        range(len(enc_chunks)),
        enc_chunks,
        nd_v_chunks,
        region,
        backend_shape,
        strict=True,
    ):
        for i, chunk in enumerate(v_chunks[1:-1]):
            if chunk % chunk_size:
                raise ValueError(
                    base_error.format(
                        v_chunk_pos=i + 1,
                        v_chunk_pos_next=i + 2,
                        v_chunk_size=chunk,
                        axis=axis,
                        name=name,
                        chunk_size=chunk_size,
                        region=interval,
                        enc_chunks=enc_chunks,
                    )
                )

        interval_start = interval.start or 0

        if len(v_chunks) > 1:
            # The first border size is the amount of data that needs to be updated on the
            # first chunk taking into account the region slice.
            first_border_size = chunk_size
            if allow_partial_chunks:
                first_border_size = chunk_size - interval_start % chunk_size

            if (v_chunks[0] - first_border_size) % chunk_size:
                raise ValueError(
                    base_error.format(
                        v_chunk_pos=0,
                        v_chunk_pos_next=0,
                        v_chunk_size=v_chunks[0],
                        axis=axis,
                        name=name,
                        chunk_size=chunk_size,
                        region=interval,
                        enc_chunks=enc_chunks,
                    )
                )

        if not allow_partial_chunks:
            region_stop = interval.stop or size

            error_on_last_chunk = base_error.format(
                v_chunk_pos=len(v_chunks) - 1,
                v_chunk_pos_next=len(v_chunks) - 1,
                v_chunk_size=v_chunks[-1],
                axis=axis,
                name=name,
                chunk_size=chunk_size,
                region=interval,
                enc_chunks=enc_chunks,
            )
            if interval_start % chunk_size:
                # The last chunk which can also be the only one is a partial chunk
                # if it is not aligned at the beginning
                raise ValueError(error_on_last_chunk)

            if np.ceil(region_stop / chunk_size) == np.ceil(size / chunk_size):
                # If the region is covering the last chunk then check
                # if the reminder with the default chunk size
                # is equal to the size of the last chunk
                if v_chunks[-1] % chunk_size != size % chunk_size:
                    raise ValueError(error_on_last_chunk)
            elif v_chunks[-1] % chunk_size:
                raise ValueError(error_on_last_chunk)
